renvoAsmStorePrimaryMemSecondaryDisp(a, 0)
renvoAsmPrimaryImm(a, backingSize/elemSize)
renvoAsmStorePrimaryMemSecondaryDisp(a, 16)
renvoAsmMarkLabel(a, okLabel)
