end := renvoTokEnd(p, e.tok)
if start >= end {
return false
}
c0 := p.src[start]
var c1 byte
if start+1 < end {
c1 = p.src[start+1]
}
if !renvoIsComparisonChars(c0, c1) {
return false
}
