(renvoExprHasUnsignedIntType(g, ep, leftIndex) || renvoExprHasUnsignedIntType(g, ep, rightIndex) ||
renvoResolveType(g.meta, leftType).kind == renvoTypePointer ||
renvoResolveType(g.meta, rightType).kind == renvoTypePointer)
