nativeABI := renvoTypeUsesNativeABI(g.meta, baseType)
fieldType := renvoResolveType(g.meta, renvoInferParsedExprType(g, ep, idx))
fieldSize := renvoNativeScalarStorageSize(g.c.renvoNativeIntSize, fieldType.kind)
