targetStart, targetEnd := renvoAsmCopyObjectText(a, src, decl.relocationTargetStart, decl.relocationTargetEnd)
relocationOffset, addend := offset, decl.relocationAddend
if decl.kind == renvoObjectDeclStaticCall {

relocationOffset++
addend -= 4
}
