func renvoFloatComparisonChars(p *renvoProgram, tok int) (byte, byte, bool) {
if tok < 0 || tok >= renvoTokCount(p) {
return 0, 0, false
}
start := renvoTokStart(p, tok)
end := renvoTokEnd(p, tok)
if start >= end {
return 0, 0, false
}
c0 := p.src[start]
c1 := byte(0)
if start+1 < end {
c1 = p.src[start+1]
}
return c0, c1, renvoIsComparisonChars(c0, c1)
}

