const __renvoSoftMant64 uint = 52
const __renvoSoftExp64 uint = 11
const __renvoSoftBias64 = -1023
const __renvoSoftNaN64 uint64 = 0x7ff8000000000000
const __renvoSoftInf64 uint64 = 0x7ff0000000000000
