func renvoUnitValidRange(limit int, start int, end int) bool {
if start < 0 || end < start {
return false
}
return end <= limit
}

func renvoUnitValidTokenRange(limit int, start int, end int) bool {
if start < 0 || end < start {
return false
}
return end <= limit
}
